/**
 * Closing is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. Closing is final: a closed
 * workspace is refused as a conflict, and the subscription and queued webhook
 * deliveries end at the same instant the workspace does.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const now = new Date();
  const closed = await orgRepo.archiveOrg(input.orgId, now);

  if ((await subscriptionRepo.findSubscription(input.orgId)) !== null) {
    await subscriptionRepo.cancelSubscription(input.orgId, toIsoTimestamp(now));
  }
  await webhookRepo.cancelPendingDeliveries(input.orgId, "workspace was closed");

  return closed;
}

